head.script:
scwin.trigger2_onclick = function(e) {
    var options = {
        'title': "포탈공지" + cnt, // 상단 타이틀바의 이름 				
        'id': "main" + cnt++, // widget의 ID
        'src': "/cobaco/1109/page01.xml", // 호출할 widget 주소 
        'scope': true, // 항상 true로 설정할 것을 권장 함. false일 경우 각 위젯의 id값이 중복될 수 없다.
        'x': 0, // 위젯 생성 위치 x값 widgetContainer에 생성한 cols를 기준으로 위치를 정한다.
        'y': 1, // 위젯 생성 위치 y값 widgetContainer에 생성한 cols를 기준으로 위치를 정한다.
        'unitWidth': 2, // 위젯 width 값. cols를 기준으로 설정한다.
        'unitHeight': 2 // 위젯 height 값. cols를 기준으로 설정한다.
    };
    widgetContainer1.addWidgets(options);
    widgetContainer1.addWidgets({
        'title': "포탈공지" + cnt,
        'id': "main" + cnt++,
        'src': "/cobaco/1109/page01.xml",
        'scope': true,
        'x': 4,
        'y': 1,
        'unitWidth': 3,
        'unitHeight': 3
    });
};
scwin.trigger3_onclick = function(e) {
    var widgetInfo = widgetContainer1.exportWidgets();
    alert(JSON.stringify(widgetInfo));
};
scwin.widgetContainer1_onbeforewidgetclose = function(id) {
    alert('beforeCloseFunc :: ' + id);
};
scwin.widgetContainer1_onafterwidgetclose = function(id) {
    alert('afterCloseFunc :: ' + id);
};
scwin.widgetContainer1_onwidgetfix = function(id) {
    alert('고정핀 클릭 :: ' + id);
};
scwin.widgetContainer1_onwidgetmaximize = function(id) {
    alert('최대화 클릭 :: ' + id);
};
scwin.widgetContainer1_onwidgetminimize = function(id) {
    alert('최소화 클릭 :: ' + id);
};
scwin.widgetContainer1_onwidgetrestore = function(id) {
    alert('복귀버튼 클릭 :: ' + id);
};
scwin.trigger4_onclick = function(e) {
    content_body.hide();
};
scwin.trigger5_onclick = function(e) {
    content_body.show("");
};
scwin.__resizeEle = function(widthVal) {
    WebSquare.wUnit.getJq("#content_body").css("width", widthVal);
    //var resizeEvent = window.document.createEvent('UIEvents'); 
    //resizeEvent .initUIEvent('resize', true, false, window, 0); 
    //window.dispatchEvent(resizeEvent);
}
scwin.__isHidden = function() {
    return WebSquare.wUnit.getDomById($p.id + "content_body").style.display == "none";
}
scwin.__isShowNormal = function(id, val) {
    return parseInt(WebSquare.wUnit.getDomById($p.id + id).style.width) == val;
}
scwin.__inline = function() {
    return WebSquare.wUnit.getDomById($p.id + "widgetContainer1_main0").offsetTop == WebSquare.wUnit.getDomById($p.id + "widgetContainer1_main1").offsetTop;
}
scwin.__incolumn = function() {
    return WebSquare.wUnit.getDomById($p.id + "widgetContainer1_main0").offsetLeft == WebSquare.wUnit.getDomById($p.id + "widgetContainer1_main1").offsetLeft;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    // Test step 1. 샘플파일을 실행하여 가로사이즈를 최대한 줄인 후'widget추가' 버튼을 클릭한다. 
    //1. Run the sample file to reduce the horizontal size as much as possible and click the 'Add widget' button.
    WebSquare.wUnit.addCommand("set", "scwin.__resizeEle('30%')");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 1. 위젯이 한줄로배열(세로로배열)되어 보여진다.
    //1. Widgets are displayed in a single line (vertically arranged).
    WebSquare.wUnit.addCommand("assert", "scwin.__incolumn()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 상단의 'hide'버튼을 클릭한다.
    //2. Click the 'hide' button at the top.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 2. 위젯이 숨김처리되어진다.
    //2. The widget is hidden.
    WebSquare.wUnit.addCommand("assert", "scwin.__isHidden()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 3. 브라우저의 가로사이즈를 최대한 늘리고 'show'버튼을 클릭한다.
    //3. Maximize your browser"s horizontal size and click the 'show' button.
    WebSquare.wUnit.addCommand("set", "scwin.__resizeEle('100%')");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 3. 위젯이 가로로 배열되어 보여진다.(정상)(이전에는 세로로 배열되어 보여짐)
    //3. Widgets are displayed horizontally (normal)(Previously shown vertically)
    WebSquare.wUnit.addCommand("assert", "scwin.__inline()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.cnt = 0;
    //Function unitTest
    //Created By: Sang.do
    //Created By: 12-Feb-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
